import{_ as a,o as i,c as n,a as e}from"./app.DkoUFz-u.js";const d=JSON.parse('{"title":"数据库层开发-高性能访问-数据分片-Vitess分片管理","description":"","frontmatter":{},"headers":[],"relativePath":"data/performance/sharding/tools/vitess.md","filePath":"data/performance/sharding/tools/vitess.md"}'),p={name:"data/performance/sharding/tools/vitess.md"};function t(l,s,h,_,c,o){return i(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="数据库层开发-高性能访问-数据分片-vitess分片管理" tabindex="-1">数据库层开发-高性能访问-数据分片-Vitess分片管理 <a class="header-anchor" href="#数据库层开发-高性能访问-数据分片-vitess分片管理" aria-label="Permalink to &quot;数据库层开发-高性能访问-数据分片-Vitess分片管理&quot;">​</a></h1><h2 id="一、vitess概述与分片理念" tabindex="-1">一、Vitess概述与分片理念 <a class="header-anchor" href="#一、vitess概述与分片理念" aria-label="Permalink to &quot;一、Vitess概述与分片理念&quot;">​</a></h2><h3 id="_1-1-什么是vitess" tabindex="-1">1.1 什么是Vitess <a class="header-anchor" href="#_1-1-什么是vitess" aria-label="Permalink to &quot;1.1 什么是Vitess&quot;">​</a></h3><p>Vitess是CNCF毕业的开源数据库集群系统，专为MySQL的水平扩展而设计。其核心设计理念是将单个MySQL实例的水平扩展问题转化为分片（Shard）管理问题，同时保持应用层对单库的透明访问。Vitess遵循“无共享（Shared-Nothing）”架构原则，每个分片拥有独立的MySQL实例，通过全局事务管理器和查询路由层实现分布式协调。</p><h3 id="_1-2-为什么要尽早考虑分片" tabindex="-1">1.2 为什么要尽早考虑分片 <a class="header-anchor" href="#_1-2-为什么要尽早考虑分片" aria-label="Permalink to &quot;1.2 为什么要尽早考虑分片&quot;">​</a></h3><p>传统观念中，分片是“能不碰就不碰”的底线。但Vitess大大降低了分片的痛苦，可以更早地利用分片带来的收益：</p><ul><li><strong>更小的爆炸半径</strong>：如果一个分片宕机，只影响较小比例的用户</li><li><strong>更好的资源利用率</strong>：小分片更容易在机器间高效打包，配合Kubernetes等编排系统效果更佳</li><li><strong>减少争用</strong>：MySQL在实例规模较小时运行更好，内部争用更少，副本更容易跟上主库</li><li><strong>改善运维</strong>：Schema部署等操作可以在所有分片上并行执行，大大缩短完成时间</li></ul><p>当然，分片也可能引入低效——如果数据本应在一起却被拆开了。但当数据开始增长时，分片往往不可避免。</p><h3 id="_1-3-核心架构组件" tabindex="-1">1.3 核心架构组件 <a class="header-anchor" href="#_1-3-核心架构组件" aria-label="Permalink to &quot;1.3 核心架构组件&quot;">​</a></h3><p>Vitess的分层架构包含以下核心组件：</p><ul><li><strong>VTGate</strong>：无状态代理层，负责将查询路由至正确的分片，支持连接池和负载均衡</li><li><strong>VTTablet</strong>：每个分片对应一组Tablet（MySQL实例+Vitess进程），处理实际数据存储</li><li><strong>vtctld</strong>：控制面板，提供分片管理、备份恢复等运维接口</li><li><strong>拓扑服务</strong>：分布式元数据服务，跟踪和管理服务器状态，使应用无需关心数据库拓扑变化</li></ul><h2 id="二、分片核心概念" tabindex="-1">二、分片核心概念 <a class="header-anchor" href="#二、分片核心概念" aria-label="Permalink to &quot;二、分片核心概念&quot;">​</a></h2><h3 id="_2-1-keyspace-键空间" tabindex="-1">2.1 Keyspace（键空间） <a class="header-anchor" href="#_2-1-keyspace-键空间" aria-label="Permalink to &quot;2.1 Keyspace（键空间）&quot;">​</a></h3><p>Keyspace是Vitess中的逻辑数据库。一个未分片的Keyspace只有一个分片（通常命名为<code>0</code>或<code>-</code>）。分片的Keyspace将大型数据库拆分成更小的部分，将每个表的行分布到不同的分片中。</p><h3 id="_2-2-shard-分片" tabindex="-1">2.2 Shard（分片） <a class="header-anchor" href="#_2-2-shard-分片" aria-label="Permalink to &quot;2.2 Shard（分片）&quot;">​</a></h3><p>分片是Keyspace的一个子集，一个Keyspace包含一个或多个分片。每个分片通常包含一个MySQL主库和多个MySQL副本，同一分片内的每个MySQL实例拥有相同的数据。副本可以服务只读流量、执行长时数据分析查询或执行管理任务。</p><h3 id="_2-3-keyspace-id-键空间id" tabindex="-1">2.3 Keyspace ID（键空间ID） <a class="header-anchor" href="#_2-3-keyspace-id-键空间id" aria-label="Permalink to &quot;2.3 Keyspace ID（键空间ID）&quot;">​</a></h3><p>Keyspace ID是决定一行数据落在哪个分片的值。<strong>基于范围的分片</strong>是指创建每个分片覆盖特定范围的Keyspace ID。Keyspace ID本身通过某种列（如用户ID）的函数计算得出，Vitess允许从多种Vindex函数中选择。</p><h3 id="_2-4-分片命名规则" tabindex="-1">2.4 分片命名规则 <a class="header-anchor" href="#_2-4-分片命名规则" aria-label="Permalink to &quot;2.4 分片命名规则&quot;">​</a></h3><p>分片名称有以下特点：</p><ul><li>表示无符号整数空间中的一个范围，左闭右开</li><li>使用十六进制表示法</li><li>左对齐，右补零</li><li><code>-80</code>表示：小于右值的所有值</li><li><code>80-</code>表示：大于或等于左值的所有值</li><li><code>-</code>表示完整的keyrange</li></ul><p>例如，<code>xxhash</code>类型的Vindex产生64位无符号整数，所有小于<code>0x8000000000000000</code>的整数落在分片<code>-80</code>中，最高位为1的则属于分片<code>80-</code>。</p><h2 id="三、vschema与vindex" tabindex="-1">三、VSchema与Vindex <a class="header-anchor" href="#三、vschema与vindex" aria-label="Permalink to &quot;三、VSchema与Vindex&quot;">​</a></h2><h3 id="_3-1-什么是vschema" tabindex="-1">3.1 什么是VSchema <a class="header-anchor" href="#_3-1-什么是vschema" aria-label="Permalink to &quot;3.1 什么是VSchema&quot;">​</a></h3><p>VSchema是Vitess中描述分片方案的元数据。当VTGate收到查询时，VSchema中的信息被用来决定如何服务该查询。应用不需要知道数据是如何分片的——这些信息存储在VSchema中，VTGate服务器用它自动路由查询。</p><h3 id="_3-2-vindex-虚拟索引" tabindex="-1">3.2 Vindex（虚拟索引） <a class="header-anchor" href="#_3-2-vindex-虚拟索引" aria-label="Permalink to &quot;3.2 Vindex（虚拟索引）&quot;">​</a></h3><p>Vindex提供了一种将列值映射到Keyspace ID的方式。由于每个分片覆盖一定范围的Keyspace ID，这个映射可用于识别某行数据所在的分片。</p><p>Vindex的优势在于其灵活性：</p><ul><li>一个表可以有多个Vindex</li><li>Vindex可以是NonUnique的，允许一个列值映射到多个Keyspace ID</li><li>Vindex可以是简单函数，也可以基于查找表</li><li>Vindex可以在多个表间共享</li><li>可以创建和使用自定义Vindex</li></ul><h3 id="_3-3-primary-vindex-主虚拟索引" tabindex="-1">3.3 Primary Vindex（主虚拟索引） <a class="header-anchor" href="#_3-3-primary-vindex-主虚拟索引" aria-label="Permalink to &quot;3.3 Primary Vindex（主虚拟索引）&quot;">​</a></h3><p>Primary Vindex类似于数据库的主键。<strong>每个分片表必须且只能定义一个Primary Vindex</strong>。Primary Vindex必须是唯一的：给定一个输入值，必须产生唯一的Keyspace ID。</p><p>在插入时，Primary Vindex产生的唯一映射决定该行数据的目标分片。Primary Vindex不仅定义了分片键，还决定了分片策略。</p><blockquote><p><strong>重要限制</strong>：Primary Vindex使用的列值在插入后不能更新，因为更改它需要将行移动到不同的分片，Vitess不支持此操作。</p></blockquote><h3 id="_3-4-secondary-vindex-辅助虚拟索引" tabindex="-1">3.4 Secondary Vindex（辅助虚拟索引） <a class="header-anchor" href="#_3-4-secondary-vindex-辅助虚拟索引" aria-label="Permalink to &quot;3.4 Secondary Vindex（辅助虚拟索引）&quot;">​</a></h3><p>Secondary Vindex是针对不使用Primary Vindex的WHERE子句提供的额外Vindex，用于优化查询。例如，如果按<code>customer_id</code>分片，但有时需要按<code>email</code>查询，可以为<code>email</code>列创建Secondary Vindex。</p><h3 id="_3-5-常用vindex类型" tabindex="-1">3.5 常用Vindex类型 <a class="header-anchor" href="#_3-5-常用vindex类型" aria-label="Permalink to &quot;3.5 常用Vindex类型&quot;">​</a></h3><p>Vitess提供了多种预定义的Vindex类型：</p><ul><li><strong>xxhash</strong>：用于数字类型</li><li><strong>unicode_loose_xxhash</strong>：用于文本列</li><li><strong>binary_md5</strong>：用于二进制列</li></ul><p>这些Vindex类型都是Unique的，可以用作Primary Vindex。</p><h3 id="_3-6-分片键-sharding-key-的选择" tabindex="-1">3.6 分片键（Sharding Key）的选择 <a class="header-anchor" href="#_3-6-分片键-sharding-key-的选择" aria-label="Permalink to &quot;3.6 分片键（Sharding Key）的选择&quot;">​</a></h3><p>选择强大的分片键（即Primary Vindex）至关重要，应考虑以下特质：</p><ol><li><strong>在查询WHERE子句中的频率</strong>：最高QPS的查询应能使用分片键定位</li><li><strong>映射函数的唯一性</strong>：Vindex应将列值映射到唯一的Keyspace ID</li><li><strong>行共置</strong>：为多个表使用相同的Primary Vindex，使关联的行自动位于同一分片，支持单分片Join和事务</li><li><strong>高基数</strong>：产生足够多的Keyspace ID，为重分片时的负载均衡提供精细控制</li></ol><p>常见的主Vindex通常是用户ID或客户ID。如果有明确的分片键（如大多数表中都有的列），创建VSchema就很简单——只需将该列指定为每个表的Primary Vindex。</p><h3 id="_3-7-vschema配置示例" tabindex="-1">3.7 VSchema配置示例 <a class="header-anchor" href="#_3-7-vschema配置示例" aria-label="Permalink to &quot;3.7 VSchema配置示例&quot;">​</a></h3><p>以下是一个分片Keyspace的VSchema配置示例，使用<code>customer_id</code>作为Primary Vindex，类型为<code>xxhash</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">{</span></span>
<span class="line"><span class="__shiki_dzsirb">  &quot;sharded&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_dzsirb">true</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_dzsirb">  &quot;vindexes&quot;</span><span class="__shiki_140thh">: {</span></span>
<span class="line"><span class="__shiki_dzsirb">    &quot;xxhash&quot;</span><span class="__shiki_140thh">: {</span></span>
<span class="line"><span class="__shiki_dzsirb">      &quot;type&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;xxhash&quot;</span></span>
<span class="line"><span class="__shiki_140thh">    }</span></span>
<span class="line"><span class="__shiki_140thh">  },</span></span>
<span class="line"><span class="__shiki_dzsirb">  &quot;tables&quot;</span><span class="__shiki_140thh">: {</span></span>
<span class="line"><span class="__shiki_dzsirb">    &quot;customer&quot;</span><span class="__shiki_140thh">: {</span></span>
<span class="line"><span class="__shiki_dzsirb">      &quot;column_vindexes&quot;</span><span class="__shiki_140thh">: [</span></span>
<span class="line"><span class="__shiki_140thh">        {</span></span>
<span class="line"><span class="__shiki_dzsirb">          &quot;column&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;customer_id&quot;</span><span class="__shiki_140thh">,</span></span>
<span class="line"><span class="__shiki_dzsirb">          &quot;name&quot;</span><span class="__shiki_140thh">: </span><span class="__shiki_mdbnqw">&quot;xxhash&quot;</span></span>
<span class="line"><span class="__shiki_140thh">        }</span></span>
<span class="line"><span class="__shiki_140thh">      ]</span></span>
<span class="line"><span class="__shiki_140thh">    }</span></span>
<span class="line"><span class="__shiki_140thh">  }</span></span>
<span class="line"><span class="__shiki_140thh">}</span></span></code></pre></div><p>对应的表Schema：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1itgoe">CREATE</span><span class="__shiki_1itgoe"> TABLE</span><span class="__shiki_1t8gfj"> customer</span><span class="__shiki_140thh"> (</span></span>
<span class="line"><span class="__shiki_140thh">  customer_id </span><span class="__shiki_1itgoe">bigint</span><span class="__shiki_140thh">, </span></span>
<span class="line"><span class="__shiki_140thh">  uname </span><span class="__shiki_1itgoe">varchar</span><span class="__shiki_140thh">(</span><span class="__shiki_dzsirb">128</span><span class="__shiki_140thh">), </span></span>
<span class="line"><span class="__shiki_1itgoe">  PRIMARY KEY</span><span class="__shiki_140thh">(customer_id)</span></span>
<span class="line"><span class="__shiki_140thh">);</span></span></code></pre></div><p>也可使用DDL方式：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1itgoe">ALTER</span><span class="__shiki_140thh"> VSchema </span><span class="__shiki_1itgoe">ON</span><span class="__shiki_dzsirb"> customer</span><span class="__shiki_140thh">.</span><span class="__shiki_dzsirb">customer</span><span class="__shiki_1itgoe"> ADD</span><span class="__shiki_140thh"> VINDEX xxhash(customer_id) </span><span class="__shiki_1itgoe">USING</span><span class="__shiki_140thh"> xxhash;</span></span></code></pre></div><h2 id="四、分片管理操作" tabindex="-1">四、分片管理操作 <a class="header-anchor" href="#四、分片管理操作" aria-label="Permalink to &quot;四、分片管理操作&quot;">​</a></h2><h3 id="_4-1-管理工具" tabindex="-1">4.1 管理工具 <a class="header-anchor" href="#_4-1-管理工具" aria-label="Permalink to &quot;4.1 管理工具&quot;">​</a></h3><p>Vitess提供以下管理工具：</p><ul><li><strong>vtctl/vtctlclient</strong>：命令行工具，用于管理Vitess集群</li><li><strong>vtctldclient</strong>：推荐使用的客户端-服务器模式工具</li><li><strong>Vitess Operator</strong>：在Kubernetes上自动化管理Vitess，可部署任意数量的集群、Cell、Keyspace、Shard和Tablet</li></ul><h3 id="_4-2-关键管理命令" tabindex="-1">4.2 关键管理命令 <a class="header-anchor" href="#_4-2-关键管理命令" aria-label="Permalink to &quot;4.2 关键管理命令&quot;">​</a></h3><p><strong>Keyspace管理</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd"># 删除Keyspace</span></span>
<span class="line"><span class="__shiki_1t8gfj">DeleteKeyspace</span><span class="__shiki_140thh"> [--recursive] </span><span class="__shiki_1itgoe">&lt;</span><span class="__shiki_140thh">keyspace</span><span class="__shiki_1itgoe">&gt;</span></span></code></pre></div><p><strong>Shard管理</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd"># 查看分片复制位置</span></span>
<span class="line"><span class="__shiki_1t8gfj">ShardReplicationPositions</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">keyspace/shar</span><span class="__shiki_140thh">d</span><span class="__shiki_1itgoe">&gt;</span></span>
<span class="line"><span class="__shiki_21nrsd"># 列出分片中的所有Tablet</span></span>
<span class="line"><span class="__shiki_1t8gfj">ListShardTablets</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">keyspace/shar</span><span class="__shiki_140thh">d</span><span class="__shiki_1itgoe">&gt;</span></span></code></pre></div><p><strong>VSchema管理</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd"># 应用VSchema配置</span></span>
<span class="line"><span class="__shiki_1t8gfj">ApplyVSchema</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">keyspac</span><span class="__shiki_140thh">e</span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">vschema_jso</span><span class="__shiki_140thh">n</span><span class="__shiki_1itgoe">&gt;</span></span></code></pre></div><h3 id="_4-3-初始分片" tabindex="-1">4.3 初始分片 <a class="header-anchor" href="#_4-3-初始分片" aria-label="Permalink to &quot;4.3 初始分片&quot;">​</a></h3><p>将未分片的Keyspace转换为分片Keyspace，通常通过以下步骤：</p><ol><li>创建目标分片（如<code>-80</code>和<code>80-</code>）</li><li>使用Reshard工作流将数据从源分片复制到目标分片</li><li>切换流量</li><li>清理源分片</li></ol><h2 id="五、重分片-resharding" tabindex="-1">五、重分片（Resharding） <a class="header-anchor" href="#五、重分片-resharding" aria-label="Permalink to &quot;五、重分片（Resharding）&quot;">​</a></h2><h3 id="_5-1-什么是重分片" tabindex="-1">5.1 什么是重分片 <a class="header-anchor" href="#_5-1-什么是重分片" aria-label="Permalink to &quot;5.1 什么是重分片&quot;">​</a></h3><p>Vitess支持在<strong>在线集群</strong>上更改分片数量。这可以是：</p><ul><li><strong>拆分</strong>：将一个或多个分片拆分成更小的分片</li><li><strong>合并</strong>：将相邻分片合并成更大的分片</li></ul><p>重分片过程中，源分片的数据被复制到目标分片，追平复制延迟，然后与原始数据比对以确保数据完整性，最后将在线服务切换到目标分片，删除源分片。</p><h3 id="_5-2-vreplication-数据移动引擎" tabindex="-1">5.2 VReplication：数据移动引擎 <a class="header-anchor" href="#_5-2-vreplication-数据移动引擎" aria-label="Permalink to &quot;5.2 VReplication：数据移动引擎&quot;">​</a></h3><p>VReplication是Vitess的核心数据移动引擎，从源到目标以近实时方式流式传输binlog事件。它支撑了以下功能：</p><ul><li><strong>MoveTables</strong>：将表迁移到Vitess或跨Keyspace迁移</li><li><strong>Reshard</strong>：按需扩展或缩减Keyspace</li><li><strong>Materialize</strong>：物化视图</li><li><strong>LookupVindex</strong>：创建和回填查找Vindex</li></ul><h3 id="_5-3-reshard工作流生命周期" tabindex="-1">5.3 Reshard工作流生命周期 <a class="header-anchor" href="#_5-3-reshard工作流生命周期" aria-label="Permalink to &quot;5.3 Reshard工作流生命周期&quot;">​</a></h3><p>使用Reshard命令管理重分片工作流：</p><p><strong>1. 创建工作流</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">vtctldclient</span><span class="__shiki_mdbnqw"> Reshard</span><span class="__shiki_dzsirb"> --workflow</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">workflo</span><span class="__shiki_140thh">w</span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_dzsirb"> --target-keyspace</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">target-keyspac</span><span class="__shiki_140thh">e</span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_mdbnqw"> create</span><span class="__shiki_dzsirb"> --source-shards</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">source-shard</span><span class="__shiki_140thh">s</span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_dzsirb"> --target-shards</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">target-shard</span><span class="__shiki_140thh">s</span><span class="__shiki_1itgoe">&gt;</span></span></code></pre></div><p>例如，将单分片<code>0</code>拆分为<code>-80</code>和<code>80-</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">vtctldclient</span><span class="__shiki_mdbnqw"> Reshard</span><span class="__shiki_dzsirb"> --workflow</span><span class="__shiki_mdbnqw"> cust2cust</span><span class="__shiki_dzsirb"> --target-keyspace</span><span class="__shiki_mdbnqw"> customer</span><span class="__shiki_mdbnqw"> create</span><span class="__shiki_dzsirb"> --source-shards</span><span class="__shiki_mdbnqw"> &#39;0&#39;</span><span class="__shiki_dzsirb"> --target-shards</span><span class="__shiki_mdbnqw"> &#39;-80,80-&#39;</span></span></code></pre></div><p><strong>2. 监控进度</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">vtctldclient</span><span class="__shiki_mdbnqw"> Reshard</span><span class="__shiki_dzsirb"> --workflow</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">workflo</span><span class="__shiki_140thh">w</span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_dzsirb"> --target-keyspace</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">target-keyspac</span><span class="__shiki_140thh">e</span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_mdbnqw"> show</span></span>
<span class="line"><span class="__shiki_1t8gfj">vtctldclient</span><span class="__shiki_mdbnqw"> Reshard</span><span class="__shiki_dzsirb"> --workflow</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">workflo</span><span class="__shiki_140thh">w</span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_dzsirb"> --target-keyspace</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">target-keyspac</span><span class="__shiki_140thh">e</span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_mdbnqw"> status</span></span></code></pre></div><p><code>status</code>命令报告复制进度百分比和复制延迟。</p><p><strong>3. 数据校验</strong>：使用VDiff确认数据正确复制</p><p><strong>4. 切换流量</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">vtctldclient</span><span class="__shiki_mdbnqw"> Reshard</span><span class="__shiki_dzsirb"> --workflow</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">workflo</span><span class="__shiki_140thh">w</span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_dzsirb"> --target-keyspace</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">target-keyspac</span><span class="__shiki_140thh">e</span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_mdbnqw"> switchtraffic</span></span></code></pre></div><p>现在可以一次性切换所有流量（主库、副本、只读），也可按任意顺序切换。VTGate在切换流量时可以缓冲查询。</p><p><strong>5. 清理</strong>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1t8gfj">vtctldclient</span><span class="__shiki_mdbnqw"> Reshard</span><span class="__shiki_dzsirb"> --workflow</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">workflo</span><span class="__shiki_140thh">w</span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_dzsirb"> --target-keyspace</span><span class="__shiki_1itgoe"> &lt;</span><span class="__shiki_mdbnqw">target-keyspac</span><span class="__shiki_140thh">e</span><span class="__shiki_1itgoe">&gt;</span><span class="__shiki_mdbnqw"> complete</span></span></code></pre></div><h3 id="_5-4-序列-sequences-处理" tabindex="-1">5.4 序列（Sequences）处理 <a class="header-anchor" href="#_5-4-序列-sequences-处理" aria-label="Permalink to &quot;5.4 序列（Sequences）处理&quot;">​</a></h3><p>在分片环境中，MySQL的<code>auto_increment</code>不能正常工作。Vitess提供<strong>序列（Sequence）</strong> 作为替代方案。</p><p>序列表是未分片的单行表，Vitess用它生成单调递增的ID：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_1itgoe"> next</span><span class="__shiki_1itgoe"> value</span><span class="__shiki_1itgoe"> FROM</span><span class="__shiki_140thh"> customer_seq</span></span>
<span class="line"><span class="__shiki_1itgoe">SELECT</span><span class="__shiki_1itgoe"> next</span><span class="__shiki_140thh"> N </span><span class="__shiki_1itgoe">values</span><span class="__shiki_1itgoe"> FROM</span><span class="__shiki_140thh"> customer_seq</span></span></code></pre></div><p>序列表Schema示例：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_1itgoe">CREATE</span><span class="__shiki_1itgoe"> TABLE</span><span class="__shiki_1t8gfj"> customer_seq</span><span class="__shiki_140thh"> (</span></span>
<span class="line"><span class="__shiki_140thh">  id </span><span class="__shiki_1itgoe">int</span><span class="__shiki_140thh">, </span></span>
<span class="line"><span class="__shiki_140thh">  next_id </span><span class="__shiki_1itgoe">bigint</span><span class="__shiki_140thh">, </span></span>
<span class="line"><span class="__shiki_140thh">  cache </span><span class="__shiki_1itgoe">bigint</span><span class="__shiki_140thh">, </span></span>
<span class="line"><span class="__shiki_1itgoe">  PRIMARY KEY</span><span class="__shiki_140thh">(id)</span></span>
<span class="line"><span class="__shiki_140thh">) COMMENT </span><span class="__shiki_mdbnqw">&#39;vitess_sequence&#39;</span><span class="__shiki_140thh">;</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_1itgoe">INSERT INTO</span><span class="__shiki_140thh"> customer_seq (id, next_id, cache) </span><span class="__shiki_1itgoe">VALUES</span><span class="__shiki_140thh"> (</span><span class="__shiki_dzsirb">0</span><span class="__shiki_140thh">, </span><span class="__shiki_dzsirb">1000</span><span class="__shiki_140thh">, </span><span class="__shiki_dzsirb">100</span><span class="__shiki_140thh">);</span></span></code></pre></div><p><code>vitess_sequence</code>注释让VTTablet将此表识别为序列。<code>cache</code>值指定一次预留和缓存的ID数量——较大的缓存值性能更好。</p><p>在VSchema中将表的列与序列表关联后，<code>INSERT</code>操作会透明地从序列表获取ID，填充新行，然后将行路由到正确的分片。</p><h2 id="六、查询路由与执行" tabindex="-1">六、查询路由与执行 <a class="header-anchor" href="#六、查询路由与执行" aria-label="Permalink to &quot;六、查询路由与执行&quot;">​</a></h2><h3 id="_6-1-vtgate的路由机制" tabindex="-1">6.1 VTGate的路由机制 <a class="header-anchor" href="#_6-1-vtgate的路由机制" aria-label="Permalink to &quot;6.1 VTGate的路由机制&quot;">​</a></h3><p>VTGate的主要功能包括：</p><ul><li>跟踪Vitess集群状态，相应路由流量</li><li>完整解析SQL查询，结合VSchema将查询定向到适当的VTTablet</li><li>将合并后的结果返回给客户端</li></ul><p>VTGate收到查询后，VSchema用于决定如何服务该查询——可能路由到单个分片，也可能发送到所有分片。</p><h3 id="_6-2-执行计划" tabindex="-1">6.2 执行计划 <a class="header-anchor" href="#_6-2-执行计划" aria-label="Permalink to &quot;6.2 执行计划&quot;">​</a></h3><p>执行计划中的路由操作符指示Vitess将工作发送到哪个目标。路由操作符通常指定：</p><ul><li>使用哪个Keyspace</li><li>Keyspace是否分片</li><li>对于分片Keyspace，使用哪个Vindex</li></ul><h3 id="_6-3-查询优化" tabindex="-1">6.3 查询优化 <a class="header-anchor" href="#_6-3-查询优化" aria-label="Permalink to &quot;6.3 查询优化&quot;">​</a></h3><p>VTGate提供查询计划分类，可通过<code>/debug/query_plans</code>端点识别未优化的查询。</p><p>对于包含分片键的查询，VTGate可以精确定位到单个分片。VTGate还感知分片元数据、集群状态和表的可用性，只将查询分散到需要的分片。</p><h2 id="七、自动化运维" tabindex="-1">七、自动化运维 <a class="header-anchor" href="#七、自动化运维" aria-label="Permalink to &quot;七、自动化运维&quot;">​</a></h2><h3 id="_7-1-vitess-operator" tabindex="-1">7.1 Vitess Operator <a class="header-anchor" href="#_7-1-vitess-operator" aria-label="Permalink to &quot;7.1 Vitess Operator&quot;">​</a></h3><p>Vitess Operator在Kubernetes上自动化Vitess的管理和维护，可自动化：</p><ul><li>部署任意数量的Vitess集群、Cell、Keyspace、Shard和Tablet</li><li>水平和垂直扩展读写能力</li></ul><h3 id="_7-2-自动化能力" tabindex="-1">7.2 自动化能力 <a class="header-anchor" href="#_7-2-自动化能力" aria-label="Permalink to &quot;7.2 自动化能力&quot;">​</a></h3><p>Vitess帮助管理数据库服务器的生命周期，支持并自动处理多种场景，包括主库故障检测和恢复。通过Kubernetes Operator可实现自动化扩缩容。</p><h2 id="八、最佳实践总结" tabindex="-1">八、最佳实践总结 <a class="header-anchor" href="#八、最佳实践总结" aria-label="Permalink to &quot;八、最佳实践总结&quot;">​</a></h2><ol><li><strong>尽早考虑分片</strong>：利用Vitess降低的分片复杂度，更早获得分片收益</li><li><strong>选择正确的分片键</strong>：基于最高QPS的查询选择Primary Vindex</li><li><strong>共置相关数据</strong>：为关联表使用相同的Primary Vindex，实现单分片Join和事务</li><li><strong>保持事务在单分片内</strong>：尽可能将事务限制在单个分片内；跨分片事务可使用2PC</li><li><strong>使用序列替代auto_increment</strong>：分片环境中使用Vitess Sequence</li><li><strong>规划重分片</strong>：数据增长时及时重分片；即使初始分片方案不理想，也可以再次重分片</li><li><strong>善用Secondary Vindex</strong>：为高频非分片键查询创建辅助Vindex</li></ol>`,114)])])}const k=a(p,[["render",t]]);export{d as __pageData,k as default};
